//! Sprint **D12-bis** — gRPC handler for `efe.v1.catalog.CatalogService`.
//!
//! This module is the **translation layer** between :
//!
//!   * the wire layer : the 6 RPCs of [`crate::proto::v1::catalog`]
//!     (proto types generated by tonic-build, declared in
//!     `protos/efe/v1/catalog.proto` since D12).
//!   * the domain layer : the trait [`crate::catalog::CatalogRegistry`]
//!     + the in-memory impl [`crate::catalog::InMemoryRegistry`]
//!     (D12, 31 unit tests post audit-fix C-1 cascade + H-4
//!     principal threading).
//!   * the observability layer : 8 instruments
//!     ([`efe_telemetry::metrics::d13_instruments`]), 16 span
//!     constants ([`efe_telemetry::spans`]), 5 typed event
//!     builders
//!     ([`efe_telemetry::events::d13_streams`]) — all D13.
//!
//! # Pattern unifié
//!
//! Each of the 6 handler methods follows this sequence (cf.
//! architecture D12-bis § 4.4) :
//!
//! ```text
//! [1] auth = guard.check(&mut req, Some(SCOPE))?      (cf. § 5)
//! [2] tenant = tenant_of(&req)                         (cf. § 5)
//! [3] assert_tenant_match(&claimed_tenant, &auth)?     (cf. § 6)
//! [4] _span = info_span!(spans::CATALOG_*, ...).entered()
//! [5] start = Instant::now()
//! [6] req = request.into_inner()
//!     domain_input = conversions::proto_to_trait(...)?
//! [7] result = self.registry.<method>(...).await
//!                  .map_err(catalog_error_to_status)?
//! [8] emit_<verb>_audit(&self.audit, ...)               (writes only)
//! [9] catalog_<verb>_duration_seconds().observe(...)
//! [10] response = conversions::trait_to_proto(result)?
//!      Ok(Response::new(response))
//! ```
//!
//! # Audit fixes inherited
//!
//! * **D12 H-4** : `delete()` threads the principal — the handler
//!   passes `auth.sub` (or empty for anonymous). Non-empty principal
//!   is the gold standard ; the `principal_present` label on
//!   `efe_audit_events_total` lets the alert
//!   `D13ObsAuditPrincipalUnknown` detect regressions.
//! * **D13 C-1** : `efe_audit_events_total` now has 4 labels
//!   `[tenant, action, op_tag, principal_present]`. The handler
//!   computes `principal_present_label(auth)` from the JWT sub.

pub mod conversions;

use std::sync::Arc;
use std::time::Instant;

use async_trait::async_trait;
use tonic::{Request as TRequest, Response as TResponse, Status};
use tracing::Instrument;

use crate::auth::{AuthGuard, Scope};
use crate::catalog::{AuditEmitter, CatalogRegistry, EvolveOp, RegisteredCatalog};
use crate::interceptors::ratelimit::check_rate_limit;
use crate::interceptors::RequestTenant;
use crate::proto::v1::catalog::{self as pb, catalog_service_server::CatalogService};
use crate::ratelimit::BucketRegistry;
use crate::services::metrics::{emit_request_completion, record_ratelimit_drop};

// =====================================================================
// Path constants — public contract for the `method` label on every
// `efe_grpc_*` series. Renaming any of these breaks dashboards and
// alerts downstream (D13 dashboards 02/03/05).
// =====================================================================

const REGISTER_CATALOG_PATH: &str = "/efe.v1.catalog.CatalogService/RegisterCatalog";
const EVOLVE_CATALOG_PATH: &str = "/efe.v1.catalog.CatalogService/EvolveCatalog";
const GET_CATALOG_PATH: &str = "/efe.v1.catalog.CatalogService/GetCatalog";
const LIST_CATALOGS_PATH: &str = "/efe.v1.catalog.CatalogService/ListCatalogs";
const LIST_CATALOG_VERSIONS_PATH: &str = "/efe.v1.catalog.CatalogService/ListCatalogVersions";
const DELETE_CATALOG_PATH: &str = "/efe.v1.catalog.CatalogService/DeleteCatalog";

// =====================================================================
// Handler struct
// =====================================================================

/// Concrete catalog-service implementation.
///
/// Holds the shared resources needed by the handler :
///
///   * `registry` — `Arc<dyn CatalogRegistry>`. Default is
///     [`crate::catalog::InMemoryRegistry`] in v0.1.13 ; D14 swaps
///     in `PostgresCatalogRegistry` invisibly. The registry is
///     constructed by `runtime::ServerBuilder::build` with the
///     operator-supplied [`crate::catalog::CatalogPolicy`] (audit
///     fix C1). The policy lives entirely on the registry side ;
///     the handler does not duplicate it (audit fix L1 — prior to
///     this fix the handler held a stray `Arc<CatalogPolicy>` that
///     was never read, marked `#[allow(dead_code)]` and silently
///     drifted from the registry's authoritative copy).
///   * `audit` — emits register/evolve/delete events via
///     `tracing::info!(target = "audit")`.
///   * `auth` + `rate_limiter` — same plumbing as the M9 admin
///     service.
pub struct CatalogServiceImpl {
    registry: Arc<dyn CatalogRegistry>,
    audit: Arc<AuditEmitter>,
    auth: Arc<AuthGuard>,
    rate_limiter: Option<Arc<BucketRegistry>>,
}

impl std::fmt::Debug for CatalogServiceImpl {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("CatalogServiceImpl")
            .field("auth_enabled", &self.auth.is_enabled())
            .field("rate_limiter", &self.rate_limiter.is_some())
            .finish()
    }
}

impl CatalogServiceImpl {
    /// Build the handler with all dependencies. Every dep is
    /// `Arc`-wrapped so the impl is cheaply cloneable.
    #[must_use]
    pub fn new(
        registry: Arc<dyn CatalogRegistry>,
        audit: Arc<AuditEmitter>,
        auth: Arc<AuthGuard>,
        rate_limiter: Option<Arc<BucketRegistry>>,
    ) -> Self {
        Self {
            registry,
            audit,
            auth,
            rate_limiter,
        }
    }

    fn tenant_of<T>(req: &TRequest<T>) -> String {
        req.extensions()
            .get::<RequestTenant>()
            .map(|t| t.0.clone())
            .unwrap_or_else(|| "anonymous".to_string())
    }

    fn principal_of<T>(req: &TRequest<T>) -> String {
        use crate::interceptors::AuthExtClaims;
        req.extensions()
            .get::<AuthExtClaims>()
            .map(|c| c.0.sub.clone())
            .unwrap_or_default()
    }
}

// =====================================================================
// Audit emission helpers — Prometheus counter only.
//
// **Important** : the `InMemoryRegistry::{register,evolve,delete}`
// methods already invoke their internal `AuditEmitter::emit_*` —
// which produces a `tracing::info!(target = "audit", ...)` line
// (mirror of the audit JSON-Schema D13). The handler MUST NOT
// re-emit on the AuditEmitter, otherwise every mutation would log
// twice.
//
// What the handler DOES emit on top of the registry's call :
//
//   * The Prometheus counter `efe_audit_events_total{tenant, action,
//     op_tag, principal_present}` — not produced by the registry.
//     D13 audit C-1 fix : the `principal_present` bool string is
//     computed from the JWT `sub` (empty → `"false"`, else
//     `"true"`).
//
// The `_audit` parameter is kept on these helpers for future
// extension — when D14-bis lands HMAC signing, the handler will
// instantiate a *different* `AuditEmitter` (signing sink) than the
// registry, and re-introduce a handler-level emit at this exact
// site.
// =====================================================================

fn principal_present_label(principal: &str) -> &'static str {
    if principal.is_empty() {
        "false"
    } else {
        "true"
    }
}

fn emit_register_audit(
    _audit: &AuditEmitter,
    auth_tenant: &str,
    principal: &str,
    _registered: &RegisteredCatalog,
) {
    efe_telemetry::metrics::d13_instruments::audit_events_total()
        .with_label_values(&[
            auth_tenant,
            "register",
            "register",
            principal_present_label(principal),
        ])
        .inc();
}

fn emit_evolve_audit(
    _audit: &AuditEmitter,
    auth_tenant: &str,
    principal: &str,
    op: &EvolveOp,
    _registered: &RegisteredCatalog,
) {
    efe_telemetry::metrics::d13_instruments::audit_events_total()
        .with_label_values(&[
            auth_tenant,
            "evolve",
            op.audit_tag(),
            principal_present_label(principal),
        ])
        .inc();
}

fn emit_delete_audit(
    _audit: &AuditEmitter,
    auth_tenant: &str,
    principal: &str,
    _key: &crate::catalog::CatalogKey,
    _force: bool,
) {
    efe_telemetry::metrics::d13_instruments::audit_events_total()
        .with_label_values(&[
            auth_tenant,
            "delete",
            "delete",
            principal_present_label(principal),
        ])
        .inc();
}

// =====================================================================
// Histogram observation helpers (D13 instruments).
//
// Manual observe (rather than start_timer / drop guard) so we can
// pick the right `result` label after the future resolves. Holding a
// `HistogramTimer` across an `.await` is technically possible but
// makes the future non-Send, which tonic rejects.
// =====================================================================

fn observe_register(tenant: &str, result_label: &str, started: Instant) {
    efe_telemetry::metrics::d13_instruments::catalog_register_duration_seconds()
        .with_label_values(&[tenant, result_label])
        .observe(started.elapsed().as_secs_f64());
}

fn observe_evolve(tenant: &str, op: &str, result_label: &str, started: Instant) {
    efe_telemetry::metrics::d13_instruments::catalog_evolve_duration_seconds()
        .with_label_values(&[tenant, op, result_label])
        .observe(started.elapsed().as_secs_f64());
}

fn observe_get(tenant: &str, include_compiled: bool, result_label: &str, started: Instant) {
    let inc = if include_compiled { "true" } else { "false" };
    efe_telemetry::metrics::d13_instruments::catalog_get_duration_seconds()
        .with_label_values(&[tenant, inc, result_label])
        .observe(started.elapsed().as_secs_f64());
}

fn observe_list(tenant: &str, result_label: &str, started: Instant) {
    efe_telemetry::metrics::d13_instruments::catalog_list_duration_seconds()
        .with_label_values(&[tenant, result_label])
        .observe(started.elapsed().as_secs_f64());
}

// =====================================================================
// Versions gauge update (used after register/evolve/delete) — best
// effort, swallows errors.
// =====================================================================

async fn refresh_versions_gauge(registry: &Arc<dyn CatalogRegistry>, tenant: &str, name: &str) {
    match registry.list_versions(tenant, name).await {
        Ok(keys) => {
            efe_telemetry::metrics::d13_instruments::catalog_versions_per_name()
                .with_label_values(&[tenant, name])
                .set(keys.len() as i64);
        }
        Err(_) => {
            // Chain may have been deleted ; reset to 0.
            efe_telemetry::metrics::d13_instruments::catalog_versions_per_name()
                .with_label_values(&[tenant, name])
                .set(0);
        }
    }
}

// =====================================================================
// Error mapping — `CatalogError` → `tonic::Status`.
//
// **Audit T-12bis-2 fix** : `Internal(_)` does NOT leak the inner
// message to the client (info disclosure : DB IPs, paths, schema).
// The original message is logged server-side at ERROR level for
// debugging via `request_id` correlation (Loki).
// =====================================================================

fn catalog_error_to_status(err: crate::catalog::CatalogError) -> Status {
    use crate::catalog::CatalogError::*;
    match err {
        NotFound(m) => Status::not_found(m),
        InvalidArgument(m) => Status::invalid_argument(m),
        PermissionDenied(m) => Status::permission_denied(m),
        QuotaExceeded(m) => Status::resource_exhausted(m),
        Conflict(m) => Status::failed_precondition(m),
        Internal(m) => {
            tracing::error!(
                target: "efe.catalog.handler",
                internal_err = %m,
                "catalog handler — internal error (sanitised before client return)",
            );
            Status::internal("internal server error")
        }
    }
}

fn result_label(success: bool) -> &'static str {
    if success {
        "ok"
    } else {
        "error"
    }
}

// =====================================================================
// Tenant assertion — D11 invariant.
//
// The auth guard already injects the tenant from the JWT into
// `RequestTenant`. The request body MAY carry a different tenant
// (claimed by the client) — we MUST refuse with `permission_denied`
// if they don't match. Otherwise a tenant with `admin:catalog:write`
// could write under any other tenant's namespace.
// =====================================================================

fn assert_tenant_match(auth_tenant: &str, claimed_tenant: &str) -> Result<(), Status> {
    if auth_tenant == claimed_tenant {
        return Ok(());
    }
    Err(Status::permission_denied(format!(
        "tenant mismatch: JWT claims {auth_tenant:?}, request claims \
         {claimed_tenant:?}",
    )))
}

// =====================================================================
// CatalogService impl
// =====================================================================

#[async_trait]
impl CatalogService for CatalogServiceImpl {
    async fn register_catalog(
        &self,
        mut req: TRequest<pb::RegisterCatalogRequest>,
    ) -> Result<TResponse<pb::CatalogHandle>, Status> {
        let started = Instant::now();
        let auth_res = self
            .auth
            .check(&mut req, Some(Scope::ADMIN_CATALOG_WRITE))
            .await;
        let tenant = Self::tenant_of(&req);
        if let Err(e) = auth_res {
            emit_request_completion(REGISTER_CATALOG_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }
        if let Err(e) = check_rate_limit(self.rate_limiter.as_ref(), &tenant) {
            record_ratelimit_drop(&tenant);
            emit_request_completion(REGISTER_CATALOG_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }

        let principal = Self::principal_of(&req);
        let inner = req.into_inner();

        if let Err(e) = assert_tenant_match(&tenant, &inner.tenant) {
            emit_request_completion(REGISTER_CATALOG_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }
        if inner.name.trim().is_empty() {
            let e = Status::invalid_argument("RegisterCatalogRequest.name is required");
            emit_request_completion(REGISTER_CATALOG_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }

        let span = tracing::info_span!(
            efe_telemetry::spans::CATALOG_REGISTER,
            tenant = %tenant,
            name = %inner.name,
        );

        let registry = Arc::clone(&self.registry);
        let audit = Arc::clone(&self.audit);
        let name = inner.name.clone();
        let principal_for_async = principal.clone();
        let tenant_for_async = tenant.clone();

        let outcome: Result<TResponse<pb::CatalogHandle>, Status> = async {
            let content = conversions::proto_content_to_trait(inner.content)?;
            let metadata = conversions::build_initial_metadata(
                &principal_for_async,
                &inner.description,
                &inner.labels,
            );
            let registered = registry
                .register(&tenant_for_async, &name, content, metadata)
                .await
                .map_err(catalog_error_to_status)?;

            emit_register_audit(&audit, &tenant_for_async, &principal_for_async, &registered);
            refresh_versions_gauge(&registry, &tenant_for_async, &name).await;

            Ok(TResponse::new(conversions::registered_to_handle(
                registered,
            )))
        }
        .instrument(span)
        .await;

        observe_register(&tenant, result_label(outcome.is_ok()), started);

        emit_request_completion(
            REGISTER_CATALOG_PATH,
            &tenant,
            &outcome.as_ref().map(|_| ()),
            started,
        );
        outcome
    }

    async fn evolve_catalog(
        &self,
        mut req: TRequest<pb::EvolveCatalogRequest>,
    ) -> Result<TResponse<pb::CatalogHandle>, Status> {
        let started = Instant::now();
        let auth_res = self
            .auth
            .check(&mut req, Some(Scope::ADMIN_CATALOG_WRITE))
            .await;
        let tenant = Self::tenant_of(&req);
        if let Err(e) = auth_res {
            emit_request_completion(EVOLVE_CATALOG_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }
        if let Err(e) = check_rate_limit(self.rate_limiter.as_ref(), &tenant) {
            record_ratelimit_drop(&tenant);
            emit_request_completion(EVOLVE_CATALOG_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }

        let principal = Self::principal_of(&req);
        let inner = req.into_inner();

        let from_key = match conversions::parse_canonical_key(&inner.from_key) {
            Ok(k) => k,
            Err(e) => {
                emit_request_completion(EVOLVE_CATALOG_PATH, &tenant, &Err(&e), started);
                return Err(e);
            }
        };
        if let Err(e) = assert_tenant_match(&tenant, &from_key.tenant) {
            emit_request_completion(EVOLVE_CATALOG_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }

        let op_proto = match inner.op {
            Some(o) => o,
            None => {
                let e = Status::invalid_argument("EvolveCatalogRequest.op is required");
                emit_request_completion(EVOLVE_CATALOG_PATH, &tenant, &Err(&e), started);
                return Err(e);
            }
        };
        let op = match conversions::proto_op_to_trait(op_proto) {
            Ok(o) => o,
            Err(e) => {
                emit_request_completion(EVOLVE_CATALOG_PATH, &tenant, &Err(&e), started);
                return Err(e);
            }
        };
        let op_tag = op.audit_tag().to_owned();

        let span = tracing::info_span!(
            efe_telemetry::spans::CATALOG_EVOLVE,
            tenant = %tenant,
            from_key = %inner.from_key,
            op = %op_tag,
        );

        let metadata = conversions::build_evolve_metadata(&principal, inner.metadata_override);
        let registry = Arc::clone(&self.registry);
        let audit = Arc::clone(&self.audit);
        let from_key_clone = from_key.clone();
        let tenant_for_async = tenant.clone();
        let principal_for_async = principal.clone();
        let op_for_async = op.clone();

        let outcome: Result<TResponse<pb::CatalogHandle>, Status> = async {
            let registered = registry
                .evolve(&from_key_clone, op_for_async.clone(), metadata)
                .await
                .map_err(catalog_error_to_status)?;
            emit_evolve_audit(
                &audit,
                &tenant_for_async,
                &principal_for_async,
                &op_for_async,
                &registered,
            );
            refresh_versions_gauge(&registry, &tenant_for_async, &from_key_clone.name).await;
            Ok(TResponse::new(conversions::registered_to_handle(
                registered,
            )))
        }
        .instrument(span)
        .await;

        observe_evolve(&tenant, &op_tag, result_label(outcome.is_ok()), started);

        emit_request_completion(
            EVOLVE_CATALOG_PATH,
            &tenant,
            &outcome.as_ref().map(|_| ()),
            started,
        );
        outcome
    }

    async fn get_catalog(
        &self,
        mut req: TRequest<pb::GetCatalogRequest>,
    ) -> Result<TResponse<pb::CanonicalCatalog>, Status> {
        let started = Instant::now();
        let auth_res = self
            .auth
            .check(&mut req, Some(Scope::ADMIN_CATALOG_READ))
            .await;
        let tenant = Self::tenant_of(&req);
        if let Err(e) = auth_res {
            emit_request_completion(GET_CATALOG_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }
        if let Err(e) = check_rate_limit(self.rate_limiter.as_ref(), &tenant) {
            record_ratelimit_drop(&tenant);
            emit_request_completion(GET_CATALOG_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }

        let inner = req.into_inner();
        let key = match conversions::parse_canonical_key(&inner.key) {
            Ok(k) => k,
            Err(e) => {
                emit_request_completion(GET_CATALOG_PATH, &tenant, &Err(&e), started);
                return Err(e);
            }
        };
        if let Err(e) = assert_tenant_match(&tenant, &key.tenant) {
            emit_request_completion(GET_CATALOG_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }

        let span = tracing::info_span!(
            efe_telemetry::spans::CATALOG_GET,
            tenant = %tenant,
            key = %inner.key,
            include_compiled = inner.include_compiled,
        );

        let registry = Arc::clone(&self.registry);
        let include_compiled = inner.include_compiled;

        let outcome: Result<TResponse<pb::CanonicalCatalog>, Status> = async {
            let registered = registry
                .get(&key, include_compiled)
                .await
                .map_err(catalog_error_to_status)?;
            Ok(TResponse::new(conversions::registered_to_canonical_proto(
                registered,
            )))
        }
        .instrument(span)
        .await;

        observe_get(
            &tenant,
            include_compiled,
            result_label(outcome.is_ok()),
            started,
        );

        emit_request_completion(
            GET_CATALOG_PATH,
            &tenant,
            &outcome.as_ref().map(|_| ()),
            started,
        );
        outcome
    }

    async fn list_catalogs(
        &self,
        mut req: TRequest<pb::ListCatalogsRequest>,
    ) -> Result<TResponse<pb::ListCatalogsResponse>, Status> {
        let started = Instant::now();
        let auth_res = self
            .auth
            .check(&mut req, Some(Scope::ADMIN_CATALOG_READ))
            .await;
        let tenant = Self::tenant_of(&req);
        if let Err(e) = auth_res {
            emit_request_completion(LIST_CATALOGS_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }
        if let Err(e) = check_rate_limit(self.rate_limiter.as_ref(), &tenant) {
            record_ratelimit_drop(&tenant);
            emit_request_completion(LIST_CATALOGS_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }

        let inner = req.into_inner();
        if let Err(e) = assert_tenant_match(&tenant, &inner.tenant) {
            emit_request_completion(LIST_CATALOGS_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }

        let span = tracing::info_span!(
            efe_telemetry::spans::CATALOG_LIST,
            tenant = %tenant,
            page_size = inner.page_size,
        );

        let registry = Arc::clone(&self.registry);
        let tenant_for_async = tenant.clone();
        let page_size = if inner.page_size <= 0 {
            100
        } else {
            inner.page_size as u32
        };
        let page_token = inner.page_token.clone();

        let outcome: Result<TResponse<pb::ListCatalogsResponse>, Status> = async move {
            let token: Option<&str> = if page_token.is_empty() {
                None
            } else {
                Some(page_token.as_str())
            };
            let page = registry
                .list_catalogs(&tenant_for_async, page_size, token)
                .await
                .map_err(catalog_error_to_status)?;
            let catalogs = page
                .catalogs
                .into_iter()
                .map(|s| pb::CatalogRefSummary {
                    tenant: s.tenant,
                    name: s.name,
                    latest_version: s.latest_version,
                    num_classes: s.num_classes,
                    num_anchors: s.num_anchors,
                })
                .collect();
            Ok(TResponse::new(pb::ListCatalogsResponse {
                catalogs,
                next_page_token: page.next_page_token,
            }))
        }
        .instrument(span)
        .await;

        observe_list(&tenant, result_label(outcome.is_ok()), started);

        emit_request_completion(
            LIST_CATALOGS_PATH,
            &tenant,
            &outcome.as_ref().map(|_| ()),
            started,
        );
        outcome
    }

    async fn list_catalog_versions(
        &self,
        mut req: TRequest<pb::ListCatalogVersionsRequest>,
    ) -> Result<TResponse<pb::ListCatalogVersionsResponse>, Status> {
        let started = Instant::now();
        let auth_res = self
            .auth
            .check(&mut req, Some(Scope::ADMIN_CATALOG_READ))
            .await;
        let tenant = Self::tenant_of(&req);
        if let Err(e) = auth_res {
            emit_request_completion(LIST_CATALOG_VERSIONS_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }
        if let Err(e) = check_rate_limit(self.rate_limiter.as_ref(), &tenant) {
            record_ratelimit_drop(&tenant);
            emit_request_completion(LIST_CATALOG_VERSIONS_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }

        let inner = req.into_inner();
        if let Err(e) = assert_tenant_match(&tenant, &inner.tenant) {
            emit_request_completion(LIST_CATALOG_VERSIONS_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }
        if inner.name.trim().is_empty() {
            let e = Status::invalid_argument("ListCatalogVersionsRequest.name is required");
            emit_request_completion(LIST_CATALOG_VERSIONS_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }

        let span = tracing::info_span!(
            efe_telemetry::spans::CATALOG_LIST_VERSIONS,
            tenant = %tenant,
            name = %inner.name,
        );

        let registry = Arc::clone(&self.registry);
        let tenant_for_async = tenant.clone();
        let name = inner.name.clone();

        let outcome: Result<TResponse<pb::ListCatalogVersionsResponse>, Status> = async move {
            let keys = registry
                .list_versions(&tenant_for_async, &name)
                .await
                .map_err(catalog_error_to_status)?;
            let wires: Vec<String> = keys.iter().map(|k| k.to_wire()).collect();
            Ok(TResponse::new(pb::ListCatalogVersionsResponse {
                keys: wires,
            }))
        }
        .instrument(span)
        .await;

        observe_list(&tenant, result_label(outcome.is_ok()), started);

        emit_request_completion(
            LIST_CATALOG_VERSIONS_PATH,
            &tenant,
            &outcome.as_ref().map(|_| ()),
            started,
        );
        outcome
    }

    async fn delete_catalog(
        &self,
        mut req: TRequest<pb::DeleteCatalogRequest>,
    ) -> Result<TResponse<()>, Status> {
        let started = Instant::now();
        let auth_res = self
            .auth
            .check(&mut req, Some(Scope::ADMIN_CATALOG_WRITE))
            .await;
        let tenant = Self::tenant_of(&req);
        if let Err(e) = auth_res {
            emit_request_completion(DELETE_CATALOG_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }
        if let Err(e) = check_rate_limit(self.rate_limiter.as_ref(), &tenant) {
            record_ratelimit_drop(&tenant);
            emit_request_completion(DELETE_CATALOG_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }

        let principal = Self::principal_of(&req);
        let inner = req.into_inner();

        let key = match conversions::parse_canonical_key(&inner.key) {
            Ok(k) => k,
            Err(e) => {
                emit_request_completion(DELETE_CATALOG_PATH, &tenant, &Err(&e), started);
                return Err(e);
            }
        };
        if let Err(e) = assert_tenant_match(&tenant, &key.tenant) {
            emit_request_completion(DELETE_CATALOG_PATH, &tenant, &Err(&e), started);
            return Err(e);
        }

        let span = tracing::info_span!(
            efe_telemetry::spans::CATALOG_DELETE,
            tenant = %tenant,
            key = %inner.key,
            force = inner.force,
        );

        let registry = Arc::clone(&self.registry);
        let audit = Arc::clone(&self.audit);
        let key_clone = key.clone();
        let tenant_for_async = tenant.clone();
        let principal_for_async = principal.clone();
        let force = inner.force;

        let outcome: Result<TResponse<()>, Status> = async move {
            // Audit fix D12 H-4 — pass the principal extracted from
            // the auth context to the trait. Empty when auth is
            // disabled (dev mode) ; the metric label
            // `principal_present="false"` lets the alert
            // D13ObsAuditPrincipalUnknown detect this in prod.
            registry
                .delete(&key_clone, force, &principal_for_async)
                .await
                .map_err(catalog_error_to_status)?;
            emit_delete_audit(
                &audit,
                &tenant_for_async,
                &principal_for_async,
                &key_clone,
                force,
            );
            refresh_versions_gauge(&registry, &tenant_for_async, &key_clone.name).await;
            Ok(TResponse::new(()))
        }
        .instrument(span)
        .await;

        emit_request_completion(
            DELETE_CATALOG_PATH,
            &tenant,
            &outcome.as_ref().map(|_| ()),
            started,
        );
        outcome
    }
}

// =====================================================================
// Tests — handler-level (with InMemoryRegistry) ; full integration
// tests live in `tests/d12bis_catalog_*.rs`.
// =====================================================================

#[cfg(test)]
mod tests {
    use super::*;
    use crate::catalog::InMemoryRegistry;
    use std::collections::HashMap;

    fn build_handler() -> CatalogServiceImpl {
        let registry: Arc<dyn CatalogRegistry> = Arc::new(InMemoryRegistry::new());
        let audit = Arc::new(AuditEmitter::new());
        let auth = Arc::new(AuthGuard::disabled());
        CatalogServiceImpl::new(registry, audit, auth, None)
    }

    fn sample_register_req(tenant: &str, name: &str) -> pb::RegisterCatalogRequest {
        pb::RegisterCatalogRequest {
            tenant: tenant.to_owned(),
            name: name.to_owned(),
            version: "v1".to_owned(),
            content: Some(pb::CatalogContent {
                embedder: Some(pb::EmbedderSpec {
                    family: "st".to_owned(),
                    model: "mini".to_owned(),
                    dim: 384,
                    normalize: "l2".to_owned(),
                }),
                classes: vec![
                    pb::CatalogClass {
                        name: "billing".to_owned(),
                        description: "B".to_owned(),
                        canonical_sentences: vec!["refund".to_owned()],
                        color: "#000".to_owned(),
                        deprecated: false,
                    },
                    pb::CatalogClass {
                        name: "login".to_owned(),
                        description: "L".to_owned(),
                        canonical_sentences: vec!["cannot login".to_owned()],
                        color: "#000".to_owned(),
                        deprecated: false,
                    },
                ],
                cone_policy: Some(pb::ConePolicy {
                    max_projection_distance: 0.7,
                }),
                thresholds: Some(pb::ThresholdPolicy {
                    confidence_high: 0.8,
                    confidence_medium: 0.5,
                }),
            }),
            created_by: "alice@acme".to_owned(),
            description: "init".to_owned(),
            labels: HashMap::new(),
        }
    }

    #[tokio::test]
    async fn register_happy_path_with_auth_disabled() {
        let h = build_handler();
        let req = TRequest::new(sample_register_req("anonymous", "billing"));
        let resp = h.register_catalog(req).await.unwrap();
        let inner = resp.into_inner();
        assert!(inner.key.starts_with("anonymous/billing@v"));
    }

    #[tokio::test]
    async fn register_rejects_missing_content() {
        let h = build_handler();
        let mut req_payload = sample_register_req("anonymous", "billing");
        req_payload.content = None;
        let req = TRequest::new(req_payload);
        let err = h.register_catalog(req).await.unwrap_err();
        assert_eq!(err.code(), tonic::Code::InvalidArgument);
    }

    #[tokio::test]
    async fn register_rejects_empty_name() {
        let h = build_handler();
        let req = TRequest::new(sample_register_req("anonymous", "  "));
        let err = h.register_catalog(req).await.unwrap_err();
        assert_eq!(err.code(), tonic::Code::InvalidArgument);
    }

    #[tokio::test]
    async fn register_rejects_tenant_mismatch() {
        let h = build_handler();
        // Auth disabled → tenant becomes "anonymous". Body claims
        // "globex". Must be rejected.
        let req = TRequest::new(sample_register_req("globex", "billing"));
        let err = h.register_catalog(req).await.unwrap_err();
        assert_eq!(err.code(), tonic::Code::PermissionDenied);
    }

    #[tokio::test]
    async fn list_catalogs_happy_path() {
        let h = build_handler();
        // First register one.
        let _ = h
            .register_catalog(TRequest::new(sample_register_req("anonymous", "billing")))
            .await
            .unwrap();
        // Then list.
        let req = TRequest::new(pb::ListCatalogsRequest {
            tenant: "anonymous".to_owned(),
            page_size: 100,
            page_token: String::new(),
        });
        let resp = h.list_catalogs(req).await.unwrap();
        assert_eq!(resp.into_inner().catalogs.len(), 1);
    }

    #[tokio::test]
    async fn list_catalogs_rejects_tenant_mismatch() {
        let h = build_handler();
        let req = TRequest::new(pb::ListCatalogsRequest {
            tenant: "globex".to_owned(),
            page_size: 100,
            page_token: String::new(),
        });
        let err = h.list_catalogs(req).await.unwrap_err();
        assert_eq!(err.code(), tonic::Code::PermissionDenied);
    }

    #[tokio::test]
    async fn get_catalog_returns_registered_content() {
        let h = build_handler();
        let resp = h
            .register_catalog(TRequest::new(sample_register_req("anonymous", "billing")))
            .await
            .unwrap();
        let key = resp.into_inner().key;
        let req = TRequest::new(pb::GetCatalogRequest {
            key: key.clone(),
            include_compiled: false,
        });
        let got = h.get_catalog(req).await.unwrap().into_inner();
        let content = got.content.unwrap();
        assert_eq!(content.classes.len(), 2);
    }

    #[tokio::test]
    async fn get_catalog_rejects_cross_tenant() {
        let h = build_handler();
        let _ = h
            .register_catalog(TRequest::new(sample_register_req("anonymous", "billing")))
            .await
            .unwrap();
        // Attempt to fetch under a different tenant prefix.
        let req = TRequest::new(pb::GetCatalogRequest {
            key: "globex/billing@v1".to_owned(),
            include_compiled: false,
        });
        let err = h.get_catalog(req).await.unwrap_err();
        assert_eq!(err.code(), tonic::Code::PermissionDenied);
    }

    #[tokio::test]
    async fn get_catalog_rejects_malformed_key() {
        let h = build_handler();
        let req = TRequest::new(pb::GetCatalogRequest {
            key: "not-a-key".to_owned(),
            include_compiled: false,
        });
        let err = h.get_catalog(req).await.unwrap_err();
        assert_eq!(err.code(), tonic::Code::InvalidArgument);
    }

    #[tokio::test]
    async fn list_catalog_versions_returns_keys_ascending() {
        let h = build_handler();
        for _ in 0..3 {
            h.register_catalog(TRequest::new(sample_register_req("anonymous", "billing")))
                .await
                .unwrap();
        }
        let req = TRequest::new(pb::ListCatalogVersionsRequest {
            tenant: "anonymous".to_owned(),
            name: "billing".to_owned(),
        });
        let resp = h.list_catalog_versions(req).await.unwrap().into_inner();
        assert_eq!(resp.keys.len(), 3);
        assert_eq!(resp.keys[0], "anonymous/billing@v1");
        assert_eq!(resp.keys[1], "anonymous/billing@v2");
        assert_eq!(resp.keys[2], "anonymous/billing@v3");
    }

    #[tokio::test]
    async fn evolve_append_class_assigns_v2() {
        let h = build_handler();
        let v1 = h
            .register_catalog(TRequest::new(sample_register_req("anonymous", "billing")))
            .await
            .unwrap()
            .into_inner();
        let req = TRequest::new(pb::EvolveCatalogRequest {
            from_key: v1.key.clone(),
            op: Some(pb::CatalogEvolutionOp {
                op: Some(pb::catalog_evolution_op::Op::AppendClass(
                    pb::AppendClassOp {
                        cls: Some(pb::CatalogClass {
                            name: "churn".to_owned(),
                            description: "C".to_owned(),
                            canonical_sentences: vec!["leaving".to_owned()],
                            color: "#000".to_owned(),
                            deprecated: false,
                        }),
                    },
                )),
            }),
            metadata_override: None,
        });
        let v2 = h.evolve_catalog(req).await.unwrap().into_inner();
        assert!(v2.key.ends_with("@v2"));
    }

    #[tokio::test]
    async fn evolve_rejects_missing_op() {
        let h = build_handler();
        let v1 = h
            .register_catalog(TRequest::new(sample_register_req("anonymous", "billing")))
            .await
            .unwrap()
            .into_inner();
        let req = TRequest::new(pb::EvolveCatalogRequest {
            from_key: v1.key,
            op: None,
            metadata_override: None,
        });
        let err = h.evolve_catalog(req).await.unwrap_err();
        assert_eq!(err.code(), tonic::Code::InvalidArgument);
    }

    #[tokio::test]
    async fn delete_catalog_removes_version() {
        let h = build_handler();
        let v1 = h
            .register_catalog(TRequest::new(sample_register_req("anonymous", "billing")))
            .await
            .unwrap()
            .into_inner();
        let req = TRequest::new(pb::DeleteCatalogRequest {
            key: v1.key.clone(),
            force: false,
        });
        h.delete_catalog(req).await.unwrap();
        // Verify : list_versions returns NotFound (chain empty → dropped).
        let req = TRequest::new(pb::ListCatalogVersionsRequest {
            tenant: "anonymous".to_owned(),
            name: "billing".to_owned(),
        });
        let err = h.list_catalog_versions(req).await.unwrap_err();
        assert_eq!(err.code(), tonic::Code::NotFound);
    }

    #[tokio::test]
    async fn delete_rejects_cross_tenant() {
        let h = build_handler();
        let _ = h
            .register_catalog(TRequest::new(sample_register_req("anonymous", "billing")))
            .await
            .unwrap();
        let req = TRequest::new(pb::DeleteCatalogRequest {
            key: "globex/billing@v1".to_owned(),
            force: false,
        });
        let err = h.delete_catalog(req).await.unwrap_err();
        assert_eq!(err.code(), tonic::Code::PermissionDenied);
    }

    #[tokio::test]
    async fn delete_referenced_without_force_returns_failed_precondition() {
        let h = build_handler();
        let v1 = h
            .register_catalog(TRequest::new(sample_register_req("anonymous", "billing")))
            .await
            .unwrap()
            .into_inner();
        // Evolve to create v2 referencing v1.
        h.evolve_catalog(TRequest::new(pb::EvolveCatalogRequest {
            from_key: v1.key.clone(),
            op: Some(pb::CatalogEvolutionOp {
                op: Some(pb::catalog_evolution_op::Op::AppendClass(
                    pb::AppendClassOp {
                        cls: Some(pb::CatalogClass {
                            name: "churn".to_owned(),
                            description: "C".to_owned(),
                            canonical_sentences: vec!["leaving".to_owned()],
                            color: "#000".to_owned(),
                            deprecated: false,
                        }),
                    },
                )),
            }),
            metadata_override: None,
        }))
        .await
        .unwrap();
        // Try to delete v1 without force → must fail with conflict.
        let req = TRequest::new(pb::DeleteCatalogRequest {
            key: v1.key,
            force: false,
        });
        let err = h.delete_catalog(req).await.unwrap_err();
        assert_eq!(err.code(), tonic::Code::FailedPrecondition);
    }

    #[tokio::test]
    async fn audit_events_total_increments_with_principal_present_true_in_dev() {
        // Auth disabled mode injects `Claims::anonymous()` which sets
        // `sub = "anonymous"` (non-empty). So `principal_present_label`
        // resolves to "true" and the counter increments under that
        // bucket. In real prod with auth on but a JWT lacking `sub`,
        // the principal would be empty → "false" — that's the alert
        // path D13ObsAuditPrincipalUnknown. Here we just verify the
        // increment fires under the correct bucket for the
        // dev-mode default.
        //
        // NOTE: the prometheus counter is process-global; other tests
        // (e.g. `register_happy_path_with_auth_disabled`) also bump
        // this exact bucket in parallel. We therefore assert a
        // monotonic delta of *at least* 1 rather than exactly 1 ; the
        // exactness invariant is upheld by the unit-level coverage of
        // `emit_register_audit` separately.
        let h = build_handler();
        let before = efe_telemetry::metrics::d13_instruments::audit_events_total()
            .with_label_values(&["anonymous", "register", "register", "true"])
            .get();
        h.register_catalog(TRequest::new(sample_register_req("anonymous", "billing")))
            .await
            .unwrap();
        let after = efe_telemetry::metrics::d13_instruments::audit_events_total()
            .with_label_values(&["anonymous", "register", "register", "true"])
            .get();
        assert!(
            after >= before + 1,
            "expected at least one increment, got before={before}, after={after}"
        );
    }

    #[test]
    fn principal_present_label_returns_false_for_empty() {
        assert_eq!(principal_present_label(""), "false");
    }

    #[test]
    fn principal_present_label_returns_true_for_filled() {
        assert_eq!(principal_present_label("alice@acme"), "true");
    }

    #[test]
    fn assert_tenant_match_accepts_equal() {
        assert!(assert_tenant_match("acme", "acme").is_ok());
    }

    #[test]
    fn assert_tenant_match_rejects_mismatch_with_permission_denied() {
        let err = assert_tenant_match("acme", "globex").unwrap_err();
        assert_eq!(err.code(), tonic::Code::PermissionDenied);
    }

    #[test]
    fn catalog_internal_error_does_not_leak_inner_message() {
        let err = catalog_error_to_status(crate::catalog::CatalogError::Internal(
            "DB at 10.0.0.7:5432 refused".to_owned(),
        ));
        assert_eq!(err.code(), tonic::Code::Internal);
        // The IP/port MUST NOT appear in the public message.
        assert_eq!(err.message(), "internal server error");
        assert!(!err.message().contains("10.0.0.7"));
    }

    #[test]
    fn catalog_not_found_error_passes_message_through() {
        let err = catalog_error_to_status(crate::catalog::CatalogError::NotFound(
            "acme/billing@v1".to_owned(),
        ));
        assert_eq!(err.code(), tonic::Code::NotFound);
        assert_eq!(err.message(), "acme/billing@v1");
    }

    #[test]
    fn catalog_invalid_argument_passes_through() {
        let err = catalog_error_to_status(crate::catalog::CatalogError::InvalidArgument(
            "embedder.dim must be > 0".to_owned(),
        ));
        assert_eq!(err.code(), tonic::Code::InvalidArgument);
    }

    #[test]
    fn catalog_quota_maps_to_resource_exhausted() {
        let err = catalog_error_to_status(crate::catalog::CatalogError::QuotaExceeded(
            "tenant exceeded names quota".to_owned(),
        ));
        assert_eq!(err.code(), tonic::Code::ResourceExhausted);
    }

    #[test]
    fn catalog_conflict_maps_to_failed_precondition() {
        let err = catalog_error_to_status(crate::catalog::CatalogError::Conflict(
            "referenced by successor".to_owned(),
        ));
        assert_eq!(err.code(), tonic::Code::FailedPrecondition);
    }
}
